import React from 'react';
import BrowserOnly from '@docusaurus/BrowserOnly';
import {amortizationSchedule} from '@site/src/lib/loan';
import {BalanceChart, SplitChart} from './ScheduleCharts';
import {useLoanLabels} from './labels';
import styles from './styles.module.css';

interface Props {
  principal: number;
  annualRate: number;
  months: number;
  kind?: 'split' | 'balance';
  title: string;
  caption?: React.ReactNode;
}

/**
 * Static figure for a fixed example. Data is generated by the same function
 * as the calculators, so text, tables and charts cannot drift apart.
 */
export default function AmortizationFigure({principal, annualRate, months, kind = 'split', title, caption}: Props) {
  const labels = useLoanLabels();
  const s = amortizationSchedule(principal, annualRate, months);
  return (
    <figure className={styles.figure}>
      <p className={styles.figureTitle}>{title}</p>
      <BrowserOnly fallback={<div className={styles.chart} />}>
        {() => (kind === 'split'
          ? <SplitChart rows={s.rows} labels={labels} />
          : <BalanceChart rows={s.rows} principal={principal} labels={labels} />)}
      </BrowserOnly>
      {caption && <figcaption className={styles.figureNote}>{caption}</figcaption>}
    </figure>
  );
}
